def single_number_pair(nums):
    xor_all = 0
    for num in nums:
        xor_all ^= num
    diff_bit = xor_all & (-xor_all)
    a = 0
    for num in nums:
        if num & diff_bit:
            a ^= num
    b = xor_all ^ a
    return sorted([a, b])
